#!/usr/bin/env Rscript
write_tsv <- function(x, p) utils::write.table(x, p, sep = "\t", quote = FALSE, row.names = FALSE)
new_data <- function(seed) { set.seed(seed); t1 <- ape::stree(4, type = "balanced"); t2 <- ape::stree(4, type = "balanced"); t1$edge.length <- rep(1, nrow(t1$edge)); t2$edge.length <- rep(1, nrow(t2$edge)); t1$tip.label <- paste0("plant", 1:4); t2$tip.label <- paste0("poll", 1:4); V <- kronecker(drmTMB:::drm_phylo_tip_covariance(t2), drmTMB:::drm_phylo_tip_covariance(t1)); g <- expand.grid(plant = t1$tip.label, pollinator = t2$tip.label); u <- as.numeric(t(chol(V)) %*% rnorm(16, sd = .55)); names(u) <- paste(g$plant, g$pollinator, sep = ":"); d <- g[rep(1:16, each = 30), ]; d$x <- rnorm(nrow(d)); d$x <- d$x - ave(d$x, interaction(d$plant,d$pollinator), FUN=mean); d$x <- d$x/sd(d$x); mu <- plogis(-.1+.35*d$x+u[paste(d$plant,d$pollinator,sep=":")]); b <- rbinom(nrow(d),1,.12); d$y <- ifelse(b==1,rbinom(nrow(d),1,.45),rbeta(nrow(d),mu/.45^2,(1-mu)/.45^2)); list(data=d,t1=t1,t2=t2) }
run_one <- function(seed, sha, runner) { s <- new_data(seed); plant_tree <- s$t1; pollinator_tree <- s$t2; f <- tryCatch(drmTMB::drmTMB(drmTMB::bf(y~x+phylo_interaction(1|plant:pollinator,tree1=plant_tree,tree2=pollinator_tree)),family=drmTMB::zero_one_beta(),data=s$data,control=list(eval.max=1000,iter.max=1000)),error=identity); if(inherits(f,"error")) return(data.frame(seed,source_sha=sha,runner_sha=runner,status="fit_error")); gr <- max(abs(f$obj$gr(f$opt$par))); tau <- f$sdpars$mu[["phylo_interaction(1 | plant:pollinator)"]]; data.frame(seed,source_sha=sha,runner_sha=runner,status="fit_ok",convergence=f$opt$convergence,pdHess=isTRUE(f$sdr$pdHess),max_gradient=gr,tau_truth=.55,tau_hat=tau,boundary_hit=!is.finite(tau)||tau<=.05||tau>=2.5) }
script <- sub("^--file=","",grep("^--file=",commandArgs(FALSE),value=TRUE)[1]); root <- normalizePath(file.path(dirname(script),"..")); setwd(root); pkgload::load_all(root,quiet=TRUE,export_all=FALSE); out <- Sys.getenv("DRMTMB_RECOVERY_OUT", unset=file.path(root,"docs/dev-log/implementation-recovery/2026-07-29-lane-c-zob-phylo-interaction-q1-local-run-1")); dir.create(out,recursive=TRUE,showWarnings=FALSE); sha <- trimws(system2("git",c("rev-parse","HEAD"),stdout=TRUE)); runner <- unname(tools::md5sum(script)); a <- do.call(rbind,lapply(2026073301:2026073304,run_one,sha=sha,runner=runner)); write_tsv(a,file.path(out,"raw-attempts.tsv")); ok <- with(a,status=="fit_ok"&convergence==0&pdHess&max_gradient<=.01&!boundary_hit); m <- if(any(ok)) mean(a$tau_hat[ok]) else NA_real_; write_tsv(data.frame(planned_attempts=4,attempted_attempts=nrow(a),passed_attempts=sum(ok),mean_tau_hat=m,decision=if(all(ok)&&abs(m/.55-1)<=.4)"PASS_POINT_RECOVERY_LOCAL" else "BLOCKED_LOCAL_FIXTURE"),file.path(out,"summary.tsv"))
set.seed(2026073399L); group <- factor(rep(paste0("g",1:16),each=30)); x <- rnorm(length(group)); x <- x-ave(x,group,FUN=mean); x <- x/sd(x); u <- rnorm(16,sd=.55); names(u)<-levels(group); mu<-plogis(-.1+.35*x+u[as.character(group)]); b<-rbinom(length(group),1,.12); iid<-data.frame(y=ifelse(b==1,rbinom(length(group),1,.45),rbeta(length(group),mu/.45^2,(1-mu)/.45^2)),x=x,group=group); f<-tryCatch(drmTMB::drmTMB(drmTMB::bf(y~x+(1|group)),family=drmTMB::zero_one_beta(),data=iid,control=list(eval.max=1000,iter.max=1000)),error=identity); if(inherits(f,"error")) z<-data.frame(status="fit_error",decision="BLOCKED_IID_FIT_CONTROL") else { tau<-f$sdpars$mu[["(1 | group)"]]; gr<-max(abs(f$obj$gr(f$opt$par))); z<-data.frame(status="fit_ok",tau_truth=.55,tau_hat=tau,convergence=f$opt$convergence,pdHess=isTRUE(f$sdr$pdHess),max_gradient=gr,decision=if(f$opt$convergence==0&&isTRUE(f$sdr$pdHess)&&gr<=.01&&tau>.05&&tau<2.5&&abs(tau/.55-1)<=.4)"PASS_IID_FIT_CONTROL" else "BLOCKED_IID_FIT_CONTROL") }; write_tsv(z,file.path(out,"iid-fit-control.tsv"))
